INSERT INTO `application_send_template` VALUES (1,'application_send_template1',_binary '<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"1\" cellpadding=\"0\" align=\"center\" bgcolor=\"#d0d0d0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">Dear <strong>{recruiter_name}</strong>, <br /><br /><strong>{jobseeker_name}</strong> has applied for this job. <br /><br />His/Her E-mail address is : <strong>{jobseeker_email_address}.</strong> <br /><br />His/Her message are as follows :</span></span><hr /><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">{content}<br />{application_link}<br />If you have any query then you can contact with us by clicking on the following link {admin_email}. <br /><br /></span></span>\r\n<p>Regards,</p>\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>____________________</div>\r\n<div>\r\n<div><strong>Sales & Admin - <a href=\"https://wantokjobs.com/\" target=\"_blank\" rel=\"noopener noreferrer\">WantokJobs.com </a></strong></div>\r\n<div> </div>\r\n<div>\r\n<div>Digi:              :+(675) 72812218</div>\r\n<div>Voda:            :+(675) 82585190</div>\r\n<div>Email             : <a href=\"mailto:sales@wantokjobs.com\" target=\"_blank\" rel=\"noopener noreferrer\">sales@wantokjobs.com</a></div