INSERT INTO `apply` VALUES (2433,'2024-01-09 10:01:58',712,27375,'I found your position posted at WantokJobs.com and I am interested in applying for the above referenced position and attach my resume accordingly.\r\n\r\nI graduated with a diploma in Banking & Finance two months ago and I am yet to receive my papers due to outstanding tuition fee however, I am enthusiastic to take this job opportunity to help assist pay off my outstanding tuition fee.\r\n\r\nThank you for your consideration and any form of acknowledgement would be highly appreciated.\r\n\r\nKind regards,\r\nMs. Vaima Digimrina',2247,'','active');
INSERT INTO `apply` VALUES (2434,'2024-01-09 10:42:32',736,27375,'I found your position posted at WantokJobs.com and I am interested in applying for the above referenced position and attach my resume accordingly.\r\n\r\nI recently graduated with a diploma in Banking & Finance and I am yet to receive my papers due to outstanding school fees however, with my past experience in administration and positive can-do attitude, I am enthusiastic to take this job opportunity to help promote your corporate mission and make sure your organizational goals and objectives are maintained with high standards.\r\n\r\nThank you for your consideration and I look forward for a positive feedback.\r\n\r\nKind regards,\r\nMs. Vaima Digimrina',2247,'','active');
