INSERT INTO `invite_friend_tmpl` VALUES (1,'invite friend template',_binary '<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"1\" cellpadding=\"0\" align=\"center\" bgcolor=\"#d0d0d0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\">\r\n<p><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">Dear <strong>{to_email_address}</strong>,<br /><br />You have received an invitation from <strong>{from_email_name}</strong> to become a member of WantokJobs.com.<br /><br />To be a part of </span><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">WantokJobs.</span><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">com... please {click_here} .<br /><br /><br /><strong>Thanks And Regards,<br />{from_email_name}</strong></span></p>\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>____________________</div>\r\n<div>\r\n<div><strong>Sales & Admin - <a href=\"https://wantokjobs.com/\" target=\"_blank\" rel=\"noopener noreferrer\">WantokJobs.com </a></strong></div>\r\n<div> </div>\r\n<div>Email            :  <a href=\"mailto:sales@wantokjobs.com\" target=\"_blank\" rel=\"noopener noreferrer\">sales@wantokjobs.com</a></div>\r\n<div>Website         :  <a href=\"https://wantokjobs.com/\" target=\"_blank\" rel=\"noopener noreferrer\">https://wantokjobs.com</a> </div>\r\n<div>Follow us on   : | <a href=\"https://www.facebook.com/wantokjobscom\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a> | <a href=\"https://www.linkedin.com/company/wantokjobs-com/\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn </a>| <a href=\"https://twitter.com/wantokjobs\" target=\"_blank\" rel=\"noopener noreferrer\">Twitter </a>|</div>\r\n</div>\r\n</div>\r\n<p><img src=\"https://docs.google.com/uc?export=download&id=1kNQgkf2ix-8Bhhfp1Psg5d44gvFhudBI&revid=0ByQj1tj2pKANUnF2SGhMaDRuWm50eGRhZUpsL1F5OHVKMXN3PQ\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>',_binary '<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"1\" cellpadding=\"0\" align=\"center\" bgcolor=\"#d0d0d0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\">\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\">\r\n<p><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">Dear <strong>{to_email_address}</strong>,<br /><br />You have received an invitation from <strong>{from_email_name}</strong> to become a member of WantokJobs.com.<br /><br />To be a part of </span><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">WantokJobs.</span><span style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: small;\">com... please {click_here} .<br /><br /><br /><strong>Thanks And Regards,<br />{from_email_name}</strong></span></p>\r\n<p> </p>\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>____________________</div>\r\n<div>\r\n<div><strong>Sales & Admin - <a href=\"https://wantokjobs.com/\" target