INSERT INTO `invite_friend_tmpl` VALUES (2,'Invite Friend - Wantokjobs.com',_binary '<p>Dear Sir/Mdam</p>\r\n<p>You have been invited by a friend to join Wantokjobs.com</p>\r\n<p> We are PNG\'s latest most advance and fully automated Job Board. Please sign up with us here <a href=\"jobseeker_registration_step1.php\">https://wantokjobs.com/jobseeker_registration_step1.php</a></p>\r\n<p>If you have any questions, please contact us via our contact details below.</p>\r\n<p>Regards,</p>\r\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>____________________</div>\r\n<div>\r\n<div><strong>Sales & Admin - <a href=\"https://wantokjobs.com/\" target=\"_blank\" rel=\"noopener noreferrer\">WantokJobs.com </a></strong></div>\r\n<div> </div>\r\n<div>\r\n<div>Digi:              :+(675);
