INSERT INTO `jobs` VALUES (369,'AK9',73,NULL,'jobsite','2023-09-19 17:52:03',NULL,NULL,'2023-09-19 00:00:00','2023-09-29 23:59:59','AML Analyst','BSPPG04423','165','0','','Port Moresby',0,'0','No',NULL,NULL,'Anti-Money Laundering,Risk & Compliance','About the Role:\r\n\r\nTitle		AML Analyst\r\nReference No	BSPPG04423\r\nLocation	Port Moresby, Papua New Guinea\r\nType		Full-Time\r\n\r\nThis position is based in Port Moresby and will report to the Senior Anti-Money Laundering(AML);
