INSERT INTO `jobs` VALUES (1172,'DN2',248,NULL,'jobsite','2024-11-04 18:23:29','2024-11-04 18:25:12',NULL,'2024-11-04 00:00:00','2024-12-04 23:59:59','JOB VACANCY - Technology and Network Transformation Manager','PNGD1','165','0','','Port Moresby',0,'0','No',NULL,NULL,'Leadership,Project Management,Cybersecurity,Network Optimization,Digital Innovation','Position Overview: The Technology and Network Transformation Manager will spearhead the strategic overhaul of our technology infrastructure and network systems. This role is pivotal in driving digital innovation and ensuring optimal network performance.','<p> </p>\r\n<p><strong>Key Responsibilities:</strong></p>\r\n<ul>\r\n<li>Develop and execute a comprehensive technology transformation roadmap.</li>\r\n<li>Optimize network performance and reliability.</li>\r\n<li>Lead digital innovation initiatives across the organization.</li>\r\n<li>Manage and coordinate cross-functional project teams.</li>\r\n<li>Ensure robust cybersecurity measures are in place.</li>\r\n<li>Implement and manage cloud-based solutions, IoT, SD-WAN, 5G, and automation technologies.</li>\r\n</ul>','1','Yes','36','72','27','Yes','Yes','','',0,0.000000,0.000000,'No');
