INSERT INTO `jobs` VALUES (1469,'EQ9',304,NULL,'jobsite','2025-04-03 05:47:24',NULL,NULL,'2025-04-03 00:00:00','2025-04-17 23:59:59','Agents','job#1104','165','0','','Across Papua New Guinea',0,'0','No',NULL,NULL,'Sales Techniques,Communication Skills,Negotiation Skills','National Finance is expanding its network of accredited Agents across Papua New Guinea, and we want you to be part of our growth.\r\n\r\nKey Requirements\r\n\r\nPrevious Sales experience\r\nPositive, can-do attitude\r\nSmartphone with Excel/Word (or equivalent);
INSERT INTO `jobs` VALUES (1470,'ER0',220,NULL,'jobsite','2025-04-06 01:22:54',NULL,'2025-04-06 01:23:21','2025-04-04 00:00:00','2025-04-16 23:59:59','Sales Advisor - Mt Hagen','job#1204','165','0','','Mt Hagen, Western Highlands Province',0,'0','No',NULL,NULL,'Sales Skills,Product Knowledge,Communication skills','This position will provide \"first point of contact\" support to management, employees and customers in the provision of customer advice, solutions and support to drive customer engagement and sales target level performance towards the achievement of business objective.\r\n\r\nExperience / Attributes:\r\nDiploma in Business Management or related discipline.\r\nMinimum Grade 12 Certificate.\r\n2 years’ experience in role or significant experience in a similar role.\r\nStrong Product knowledge.\r\nStrong computer literacy & working knowledge of MS Suite.\r\nStrong written & oral communication ability.\r\nStrong report writing skills.\r\nEffective time management skills.\r\nPossess excellent Customer Service qualities.\r\nStrong Influencing & Negotiating Skills.\r\nAbility to organize, plan, coordinate & communicate effectively across all levels of the business.\r\nAble to work under pressure.','<strong>Main duties / responsibilities include:</strong><br />\r\n<ul>\r\n<li>Ensure customer engagement & operation of sales are aligned & pertinent to the company policies & procedures.</li>\r\n<li>Handle incoming sales calls and conduct outgoing sales calls offering advice and information on all franchise products.</li>\r\n<li>Conduct research, data and trend analysis towards increasing customer demand and interest to improve product sales levels.</li>\r\n<li>Explain, demonstrate the operation of the unit product and provide recommendations to existing or prospective customers.</li>\r\n<li>Liaise with internal departments for all customer sales, parts and service requirements to assure ongoing process compliance.</li>\r\n<li>Work in conjunction with the Marketing department to plan, schedule and implement product promotions and advertising.</li>\r\n<li>Liaise with PDI to ensure vehicle maintenance and quality inspection is conducted and aligned with Toyota quality standards.</li>\r\n<li>Provide daily/weekly/monthly updates on all product unit sales target progress and recommend countermeasures accordingly.</li>\r\n<li>Record customer interactions, transactions & complaints to ensure confidential documents are accurate, accessible & secure.</li>\r\n<li>Establish & maintain a document control process for the tracking & update of all customer information & details.</li>\r\n</ul>','1','Yes','12','36','12','Yes','No','','',0,0.000000,0.000000,'No');
INSERT INTO `jobs` VALUES (1471,'ER1',220,NULL,'jobsite','2025-04-06 01:22:56','2025-04-06 01:30:34',NULL,'2025-04-04 00:00:00','2025-04-16 23:59:59','2 x Sales Advisor - Mt Hagen','job#1204','165','0','','Mt Hagen, Western Highlands Province',0,'0','No',NULL,NULL,'Sales Skills,Product Knowledge,Communication skills','This position will provide \"first point of contact\" support to management, employees and customers in the provision of customer advice, solutions and support to drive customer engagement and sales target level performance towards the achievement of business objective.\r\n\r\nExperience / Attributes:\r\nDiploma in Business Management or related discipline.\r\nMinimum Grade 12 Certificate.\r\n2 years’ experience in role or significant experience in a similar role.\r\nStrong Product knowledge.\r\nStrong computer literacy & working knowledge of MS Suite.\r\nStrong written & oral communication ability.\r\nStrong report writing skills.\r\nEffective time management skills.\r\nPossess excellent Customer Service qualities.\r\nStrong Influencing & Negotiating Skills.\r\nAbility to organize, plan, coordinate & communicate effectively across all levels of the business.\r\nAble to work under pressure.','<strong>Main duties / responsibilities include:</strong><br />\r\n<ul>\r\n<li>Ensure customer engagement & operation of sales are aligned & pertinent to the company policies & procedures.</li>\r\n<li>Handle incoming sales calls and conduct outgoing sales calls offering advice and information on all franchise products.</li>\r\n<li>Conduct research, data and trend analysis towards increasing customer demand and interest to improve product sales levels.</li>\r\n<li>Explain, demonstrate the operation of the unit product and provide recommendations to existing or prospective customers.</li>\r\n<li>Liaise with internal departments for all customer sales, parts and service requirements to assure ongoing process compliance.</li>\r\n<li>Work in conjunction with the Marketing department to plan, schedule and implement product promotions and advertising.</li>\r\n<li>Liaise with PDI to ensure vehicle maintenance and quality inspection is conducted and aligned with Toyota quality standards.</li>\r\n<li>Provide daily/weekly/monthly updates on all product unit sales target progress and recommend countermeasures accordingly.</li>\r\n<li>Record customer interactions, transactions & complaints to ensure confidential documents are accurate, accessible & secure.</li>\r\n<li>Establish & maintain a document control process for the tracking & update of all customer information & details.</li>\r\n</ul>','1','Yes','12','36','12','Yes','No','','',0,0.000000,0.000000,'No');
