INSERT INTO `jobs` VALUES (1509,'EU9',317,NULL,'jobsite','2025-04-29 02:01:43',NULL,NULL,'2025-04-28 00:00:00','2025-05-09 23:59:59','3 x Sales Representative','job#4104','165','0','','Port Moresby, National Capital District',0,'0','No',NULL,NULL,'Communication Skills,Active Listening,Customer Relationship,Product Knowledge','We are seeking dynamic and motivated Sales Representatives to join our team at Glow Hair Boutique.\r\n\r\nRequirements:\r\n\r\nMinimum Grade 12 certificate\r\nPrevious retail, sales, or receptionist experience\r\nBe well-presented and confident\r\nBasic communication and computer skills','Responsibilities:<br /><br />Attending to customers<br />Managing bookings and sales<br />Monitoring store presentation <br />Act as an ambassador for the Glow brand','1','Yes','0','','11','Yes','No','','',0,0.000000,0.000000,'No');
