INSERT INTO `jobs` VALUES (1544,'EY4',276,NULL,'jobsite','2025-05-26 16:55:03',NULL,NULL,'2025-05-26 00:00:00','2025-06-06 23:59:59','Quality Assurance Manager','job#2605','165','0','','Mt Hagen, Western Highlands Province',0,'0','No',NULL,NULL,'Attention to Detail,Analytical Skills,Problem-Solving & Critical Thinking,Leadership & Team Management','We are seeking to recruit a suitable candidate with leadership and managerial experience who will play an important role in the Company by ensuring that products meet agreed standards of quality. The successful candidate should be able to plan, direct or coordinate food safety and quality assurance programs and drive a culture of continued improvement within the business.\r\n\r\nKEY EXPERTISE:\r\n• A Degree or Diploma in Applied Science would be an advantage.\r\n• A minimum of 5 years of experience in a similar role within manufacturing and production industry.\r\n• Back ground in retail manufacturing industry desirable.\r\n• Has the managerial ability to plan and organize work effectively with attention to detail.\r\n• Excellent written and communications skills.\r\n• A sound understanding of the PNG Food Sanitation Act, ISO 9001:2015(QMS Management System);
INSERT INTO `jobs` VALUES (Food Safety Management System);
