INSERT INTO `jobs` VALUES (1555,'EZ5',44,NULL,'jobsite','2025-06-05 23:34:54',NULL,NULL,'2025-06-05 00:00:00','2025-06-12 23:59:59','Senior Sales Representative – Lae','job#0906','165','0','','Lae, Morobe Province',0,'0','No',NULL,NULL,'Sales Strategy & Execution,Customer Relationship Management,Product Knowledge,','Trukai Industries is seeking for an enthusiastic and driven Senior Sales Representative to join our Sales Team based in Lae, Morobe Province and will report directly to the Area Sales Manager.\r\n\r\nKey Requirements\r\n\r\n Diploma in Business or related field\r\n 5 years’ experience in similar role\r\n Previous Experience in an FMCG Company\r\n Result oriented, attention to detail and strong leadership skills\r\n Excellent sales and negotiation skills \r\n Very good customer and interpersonal skills\r\n Computer literate in Outlook, Microsoft Excel and MS Word\r\n Must have a Current Class 6 Driver’s License','<p>As a Senior Sales Representative you will be responsible for the efficient day-to-day management of all sales, customer service and product image including administration in your designated location.</p>','1','Yes','72','120','7','Yes','No','','',0,0.000000,0.000000,'No');
