INSERT INTO `jobseeker_resume1` VALUES (43,96,'Lab Technician','Enthusiastic Science Graduate seeking an entry-level position to begin my career in a high-level professional environment to learn and incorporate my skills, while making a significant contribution to the success of the company.','3,1,2,4',6,'10','Hour','Lab Technician','5,12,42,35,39','Yes','165',3,0,0,'2022-03-15','20220317013120RESUME.docx','20220317013120cv__2_.png','','<p>Jordan Peara</p>\r\n<table width=\"614\">\r\n<tbody>\r\n<tr>\r\n<td width=\"201\">\r\n<p>jordanwpeara@gmail.com</p>\r\n</td>\r\n<td width=\"92\">\r\n<p>74480115</p>\r\n</td>\r\n<td width=\"113\">\r\n<p>Port Moresby</p>\r\n</td>\r\n<td width=\"208\">\r\n<p>Papua New Guinea</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"672\">\r\n<tbody>\r\n<tr>\r\n<td width=\"672\">\r\n<p style=\"text-align: left;\"><strong>Objectives</strong></p>\r\n<p><strong>&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"672\">\r\n<p>Enthusiastic graduate with internship experiences as a laboratory technician and technical skills in chemistry lab operations. Eager to take on any task within my capabilities and actively seeking a challenging opportunity to use my knowledge to bring best talent on board as an entry candidate.&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"674\">\r\n<tbody>\r\n<tr>\r\n<td width=\"674\">\r\n<p><strong>Education</strong></p>\r\n<p><strong>&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"674\">\r\n<p>Bachelor of Sciences in Chemistry and Environmental Science</p>\r\n<p>Pacific Adventist University, Port Moresby.</p>\r\n<p>Graduated: <strong>December </strong>2019 &nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"672\">\r\n<tbody>\r\n<tr>\r\n<td width=\"672\">\r\n<p><strong>Relevant Coursework</strong></p>\r\n<p><strong>&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"672\">\r\n<p>Industrial Chemistry, Environmental Chemistry, Organic and Inorganic Chemistry, Physical Chemistry, Biochemistry, Quantitative Chemistry, Health and Safety, Sustainable Development, Waste Management, etc. in the study.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"614\">\r\n<tbody>\r\n<tr>\r\n<td width=\"614\">\r\n<p><strong>Technical Skills and Abilities</strong></p>\r\n<p><strong>&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"614\">\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Knowledgeable of ISO 17025 certified laboratory operations and ISO 14001</p>\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Experienced lab technician</p>\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Proficiency in Microsoft Office Skills</p>\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Good communication and interpersonal skills</p>\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Multi-tasking</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"638\">\r\n<tbody>\r\n<tr>\r\n<td width=\"638\">\r\n<p><strong>Experience</strong></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table width=\"659\">\r\n<tbody>\r\n<tr>\r\n<td width=\"375\">\r\n<p><strong>Laboratory Technician-</strong> Internship</p>\r\n</td>\r\n<td width=\"284\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"659\">\r\n<p>Barrick Gold Corporation-PJV, Enga</p>\r\n<p>Nov 2017 &ndash; March 2018</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" width=\"659\">\r\n<p>&middot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Worked in ISO 17025 certified laboratory and did Field Sampling preparation, carried Surface Water Sampling, Portable Water Sampling, Sewage Water Sampling, Hydrocarbon Sampling, Sediment Sampling (streams, rivers, lakes and potable waters);
