INSERT INTO `newsletters` VALUES (2,'Application Tracking System - Recruitment Made Easier!','Recruiter Registration - Simple, Easy!\r\n\r\n1. Click on Register Link Under Recruiter Menu https://wantokjobs.com/recruiter_registration.php\r\n\r\n2. Confirm Registration, Sign up for Subscription Plan and that\'s it!\r\n\r\nShare this with HR Partners to use our Advance online based Recruitment Tracking Software for FREE! More info here https://wantokjobs.com/application-tracking-system-recruitment-made-easier-.html\r\n\r\nIf you are not sure, simply contact us via SMS/WhatsApp/Call on Digi:  72812218 or Voda: 82585190 for a quick response.\r\n\r\nRegards,\r\n\r\n____________________\r\nSales & Admin - WantokJobs.com \r\n \r\nDigi:              :+(675);
