INSERT INTO `newsletters_history` VALUES (1,'Application Tracking System - Recruitment Made Easier!','Recruiter Registration - Simple, Easy!\r\n\r\n1. Click on Register Link Under Recruiter Menu https://wantokjobs.com/recruiter_registration.php\r\n\r\n2. You can register using social icons on top by clicking on the appropriate icon or fill out details.\r\n\r\n3. Confirm Registration, Sign up for Subscription Plan and that\'s it!\r\n\r\n\r\nShare this with HR Partners to use our Advance online based Recruitment Tracking Software for FREE! More info here https://wantokjobs.com/application-tracking-system-recruitment-made-easier-.html\r\n\r\nAdmin - Wantokjobs.com','','jobseeker','2023-03-27 11:24:01');
INSERT INTO `newsletters_history` VALUES (2,'Application Tracking System - Recruitment Made Easier!','Recruiter Registration - Simple, Easy!\r\n\r\n1. Click on Register Link Under Recruiter Menu https://wantokjobs.com/recruiter_registration.php\r\n\r\n2. You can register using social icons on top by clicking on the appropriate icon or fill out details.\r\n\r\n3. Confirm Registration, Sign up for Subscription Plan and that\'s it!\r\n\r\n\r\nShare this with HR Partners to use our Advance online based Recruitment Tracking Software for FREE! More info here https://wantokjobs.com/application-tracking-system-recruitment-made-easier-.html\r\n\r\nAdmin - Wantokjobs.com','','recruiter','2023-03-27 11:30:06');
