  `subject` varchar(255) NOT NULL DEFAULT '',
  `message` blob NOT NULL,
  `attachment_file` varchar(255) NOT NULL DEFAULT '',
  `sender_mark` enum('No','Yes') NOT NULL DEFAULT 'No',
  `receiver_mark` enum('No','Yes') NOT NULL DEFAULT 'No',
  `receiver_see` enum('No','Yes') NOT NULL DEFAULT 'No',
  `sender_see` enum('Yes','No') NOT NULL DEFAULT 'No',
  `receiver_mail_status` enum('active','inactive','deleted') NOT NULL DEFAULT 'active',
  `sender_mail_status` enum('active','inactive','deleted') NOT NULL DEFAULT 'active',
  `receiver_deleted` date DEFAULT NULL,
  `sender_deleted` date DEFAULT NULL,
  `inserted` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`),
)  ;
;
