  `job_short_description` text NOT NULL,
  `job_description` text NOT NULL,
  `job_type` varchar(5) NOT NULL DEFAULT '',
  `job_relocate` enum('Yes','No') NOT NULL DEFAULT 'Yes',
  `min_experience` varchar(5) NOT NULL DEFAULT '',
  `max_experience` varchar(5) NOT NULL DEFAULT '',
